import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CHxxV8OH.js";const p=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md","lastUpdated":1775890242000}'),i={name:"features.md"};function n(s,e,l,g,c,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>Agent Studio is built on a foundation of <strong>visual clarity, real-time feedback, and production readiness</strong>. Here&#39;s what makes it different.</p><h2 id="agent-builder" tabindex="-1">Agent Builder <a class="header-anchor" href="#agent-builder" aria-label="Permalink to &quot;Agent Builder&quot;">​</a></h2><p>Design your agents with a dedicated editor, not raw YAML.</p><p><strong>What you get:</strong></p><ul><li><strong>Identity tab</strong>: Define agent name, role, emoji, and background context</li><li><strong>Instructions tab</strong>: Write agent behavior rules with live markdown preview in the sidebar</li><li><strong>Capabilities tab</strong>: Search and select Tools, Skills, and MCP servers your agent can use</li><li><strong>Handoffs tab</strong>: Drag-and-drop delegation relationships to other agents in the workspace</li><li><strong>Context tab</strong>: Manage shared information this agent inherits from Skills and MCP servers</li></ul><p>Every edit is immediately reflected in the <code>.agent.md</code> file, so your agent definitions stay version-controlled and auditable.</p><h2 id="handoff-graphs" tabindex="-1">Handoff Graphs <a class="header-anchor" href="#handoff-graphs" aria-label="Permalink to &quot;Handoff Graphs&quot;">​</a></h2><p>Understand agent relationships at a glance.</p><p><strong>Visualization features:</strong></p><ul><li><strong>Interactive canvas</strong>: Zoom, pan, and explore agent networks</li><li><strong>Minimap</strong>: Always see where you are in large graphs</li><li><strong>Relationship types</strong>: Distinguish delegation flows vs. capability bridges</li><li><strong>Real-time updates</strong>: Add or remove agents; graph recalculates instantly</li><li><strong>Export ready</strong>: Copy graph as SVG or JSON for docs and presentations</li></ul><p>Spot circular dependencies, identify bottlenecks, and design scalable agent systems before they break.</p><h2 id="capabilities-layer" tabindex="-1">Capabilities Layer <a class="header-anchor" href="#capabilities-layer" aria-label="Permalink to &quot;Capabilities Layer&quot;">​</a></h2><p>See which tools, skills, and MCP servers are used—and by whom.</p><p><strong>Inspector features:</strong></p><ul><li><strong>Tools list</strong>: All registered tools with use count and agent assignments</li><li><strong>Skills directory</strong>: Browse Skills with descriptions and linked agents</li><li><strong>MCP registry</strong>: View all MCP servers and their connection status</li><li><strong>Filter by agent</strong>: Select an agent, see its exact capability set</li><li><strong>Gap detection</strong>: Identify capabilities no agent can access (orphaned tools)</li></ul><p>This layer prevents &quot;what does agent X actually have access to?&quot; confusion.</p><h2 id="workflow-orchestration" tabindex="-1">Workflow Orchestration <a class="header-anchor" href="#workflow-orchestration" aria-label="Permalink to &quot;Workflow Orchestration&quot;">​</a></h2><p>Create multi-agent workflows visually, then execute through VS Code chat.</p><p><strong>Build workflows by:</strong></p><ol><li>Creating a new workflow in the sidebar</li><li>Adding agents as sequential steps or parallel branches</li><li>Marking entry and exit points</li><li>Connecting output of one agent to input of the next</li><li>Triggering from the dashboard with context pre-loaded into chat</li></ol><p>No Python, no JSON templating. Just visual, declarative agent choreography.</p><h2 id="dashboard-overview" tabindex="-1">Dashboard Overview <a class="header-anchor" href="#dashboard-overview" aria-label="Permalink to &quot;Dashboard Overview&quot;">​</a></h2><p><strong>Your control center in VS Code:</strong></p><p>The main dashboard provides:</p><ul><li><strong>Quick stats</strong>: Agent count, active workflows, capability coverage</li><li><strong>Recent activity</strong>: Last agents edited, workflows run</li><li><strong>Global search</strong>: Find agents, workflows, or capabilities instantly</li><li><strong>Theme controls</strong>: Light/dark mode, compact/spacious layout</li><li><strong>Settings link</strong>: Configure MCP servers, tool directories, agent templates</li></ul><p>Everything you need is one click away.</p><h2 id="local-first-architecture" tabindex="-1">Local-First Architecture <a class="header-anchor" href="#local-first-architecture" aria-label="Permalink to &quot;Local-First Architecture&quot;">​</a></h2><p>Agent Studio stores everything locally in your workspace.</p><p><strong>Why this matters:</strong></p><ul><li>No cloud dependency = instant startup, zero latency</li><li>Version control your agents = audit trail, branching, rollback</li><li>Team collaboration = pull requests, code review, merge conflicts resolved like any source file</li><li>Portability = agents work offline, in any environment</li></ul><p>Your agent definitions are <code>.agent.md</code> files in your repo. Treat them like code.</p><h2 id="integration-points" tabindex="-1">Integration Points <a class="header-anchor" href="#integration-points" aria-label="Permalink to &quot;Integration Points&quot;">​</a></h2><p><strong>VS Code features you already love:</strong></p><ul><li><strong>Sidebar</strong>: Agent Studio panel always accessible</li><li><strong>Markdown preview</strong>: Live view of agent instructions as you type</li><li><strong>Search</strong>: Find agents, workflows, or capabilities across the workspace</li><li><strong>Source control</strong>: Commit agent changes alongside code</li><li><strong>Chat</strong>: Open any agent in chat with one click; context auto-copied</li></ul><p><strong>External integrations:</strong></p><ul><li><strong>Skills and Tools</strong>: Register custom capabilities that multiple agents can access</li><li><strong>MCP servers</strong>: Connect to any MCP-compatible service</li><li><strong>Webhooks</strong>: Trigger workflows programmatically</li></ul><hr><p><strong><a href="#">← Back to Features</a></strong> | <strong><a href="/agent-studio/getting-started">Explore Docs →</a></strong></p>',39)])])}const u=t(i,[["render",n]]);export{p as __pageData,u as default};
